def minimumSum(S):
    n = len(S)
    if n == 1:
        return 0

    # Find the middle of the string
    mid = n // 2

    # Check if the string can be a palindrome
    for i in range(mid):
        if S[i] != '?' and S[n - i - 1] != '?' and S[i] != S[n - i - 1]:
            return -1

    # Replace '?' with the appropriate character to form a palindrome
    for i in range(mid):
        if S[i] == '?' and S[n - i - 1] != '?':
            S = S[:i] + S[n - i - 1] + S[i+1:]
        elif S[i] != '?' and S[n - i - 1] == '?':
            S = S[:n - i - 1] + S[i] + S[n - i:]

    # Calculate the sum of differences of adjacent characters
    total_sum = 0
    for i in range(n - 1):
        total_sum += abs(ord(S[i]) - ord(S[i + 1]))

    return total_sum

